SELECT fn_cp_import_case('deonto-invitation-evenement-par-une-entreprise', '{"slug": "deonto-invitation-evenement-par-une-entreprise", "title": "Une place en tribune offerte par une société de sécurité", "theme_slug": "deontologie", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 19 heures. Hors service, une société de sécurité privée avec laquelle votre service entretient des liens professionnels indirects vous propose une place en tribune pour un événement sportif valorisant, cette invitation restant apparemment généreuse et sans contrepartie explicite mais constituant néanmoins un avantage en nature offert par un partenaire économique en lien avec votre activité professionnelle. Cette configuration, où cette invitation reste séduisante dans son principe mais où ce lien professionnel indirect avec cette société pose une question déontologique réelle, nécessite de refuser cette invitation au regard de ce lien professionnel qui existe entre votre service et cette entreprise.\n\nCette situation, caractéristique des avantages en nature proposés par des partenaires économiques qui entretiennent des liens même indirects avec l''activité professionnelle, impose une vigilance particulière face à ce type de gratification qui pourrait créer une dépendance ou une obligation implicite.\n\nCette configuration nécessite de refuser cette invitation au regard de ce lien professionnel, cette exigence restant essentielle pour préserver votre indépendance vis-à-vis de ce partenaire économique de votre service.", "questions": [{"position": 1, "max_points": 5, "label": "Comment refusez-vous cette invitation au regard du lien professionnel qui existe avec cette société ?", "hint": "Ce refus doit rester clair malgré le caractère apparemment généreux de cette invitation, cette exigence restant essentielle compte tenu du lien professionnel indirect qui existe avec cette entreprise.", "perfect": "Je refuse clairement cette invitation, cette fermeté restant nécessaire compte tenu du lien professionnel indirect qui existe entre mon service et cette société de sécurité.\n\nJe reste factuelle sur les raisons de ce refus, expliquant que ce type d''avantage ne peut être accepté compte tenu de ce lien professionnel avec cette entreprise partenaire.\n\nJe reste attentive à ne pas me laisser séduire par le caractère valorisant de cet événement sportif proposé, cette vigilance restant essentielle face à cette tentation.\n\nJe reste consciente que ce refus reste nécessaire même en l''absence de contrepartie explicite formulée par cette société à ce stade.", "points": [{"position": 1, "label": "Refuser clairement cette invitation compte tenu du lien professionnel", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : fermeté face à ce lien avec cette société.", "groups": [{"position": 1, "keywords": ["invitation refusée", "lien professionnel", "fermeté nécessaire"]}]}, {"position": 2, "label": "Expliquer factuellement que cet avantage ne peut être accepté", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Raisons liées à ce lien avec l''entreprise partenaire.", "groups": [{"position": 1, "keywords": ["raisons expliquées", "avantage refusé", "entreprise partenaire"]}]}, {"position": 3, "label": "Ne pas se laisser séduire par le caractère valorisant de cet événement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance face à cette tentation.", "groups": [{"position": 1, "keywords": ["séduction évitée", "événement valorisant", "vigilance maintenue"]}]}, {"position": 4, "label": "Reconnaître que ce refus reste nécessaire malgré l''absence de contrepartie explicite", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Refus maintenu même sans contrepartie formulée.", "groups": [{"position": 1, "keywords": ["contrepartie absente", "refus maintenu", "précaution appliquée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment évaluez-vous le risque que représente ce type de gratification pour votre indépendance professionnelle ?", "hint": "Ce risque doit être évalué avec lucidité, cette évaluation restant nécessaire pour comprendre pourquoi ce type d''invitation pose une question déontologique réelle malgré son apparence généreuse.", "perfect": "Je reste consciente que ce type de gratification pourrait progressivement créer une dépendance ou une obligation implicite envers cette société partenaire.\n\nJe reste attentive au fait que cette invitation, même sans contrepartie explicite immédiate, pourrait influencer inconsciemment mon appréciation future de cette entreprise.\n\nJe reste factuelle sur le lien professionnel indirect qui justifie cette prudence, ce lien restant suffisant pour poser une question déontologique réelle.\n\nJe reste consciente que cette vigilance doit s''appliquer à tout avantage proposé par un partenaire économique de mon service, indépendamment de sa valeur apparente.", "points": [{"position": 1, "label": "Rester consciente du risque de dépendance ou d''obligation implicite", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : risque créé par ce type de gratification.", "groups": [{"position": 1, "keywords": ["dépendance identifiée", "obligation implicite", "risque reconnu"]}]}, {"position": 2, "label": "Reconnaître le risque d''influence inconsciente future", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Invitation pouvant influencer l''appréciation future.", "groups": [{"position": 1, "keywords": ["influence future", "appréciation affectée", "invitation reçue"]}]}, {"position": 3, "label": "Rester factuelle sur le lien professionnel justifiant cette prudence", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Lien indirect suffisant pour cette question déontologique.", "groups": [{"position": 1, "keywords": ["lien professionnel", "prudence justifiée", "question déontologique"]}]}, {"position": 4, "label": "Appliquer cette vigilance à tout avantage d''un partenaire économique", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance indépendante de la valeur de l''avantage.", "groups": [{"position": 1, "keywords": ["vigilance générale", "partenaire économique", "valeur relativisée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous cette situation vis-à-vis de cette société qui vous a proposé cette invitation ?", "hint": "Cette gestion doit rester courtoise malgré ce refus nécessaire, cette conciliation restant appropriée pour préserver une relation professionnelle correcte avec ce partenaire économique.", "perfect": "Je reste courtoise dans la formulation de ce refus envers cette société, cette attitude restant appropriée pour préserver une relation professionnelle correcte.\n\nJe reste factuelle sur les raisons déontologiques de ce refus, cette transparence restant utile pour que cette société comprenne cette limite qui s''impose à moi.\n\nJe reste attentive à signaler cette invitation à ma hiérarchie, cette information restant utile pour la vigilance institutionnelle sur ce type de sollicitation.\n\nJe reste vigilante face à d''éventuelles nouvelles sollicitations de la part de cette société ou d''autres partenaires économiques à l''avenir.", "points": [{"position": 1, "label": "Rester courtoise dans la formulation de ce refus", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : relation professionnelle préservée.", "groups": [{"position": 1, "keywords": ["courtoisie maintenue", "relation préservée", "refus formulé"]}]}, {"position": 2, "label": "Rester factuelle sur les raisons déontologiques de ce refus", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Transparence utile pour la compréhension de cette limite.", "groups": [{"position": 1, "keywords": ["raisons déontologiques", "transparence assurée", "limite comprise"]}]}, {"position": 3, "label": "Signaler cette invitation à la hiérarchie", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Information utile pour la vigilance institutionnelle.", "groups": [{"position": 1, "keywords": ["invitation signalée", "vigilance institutionnelle", "hiérarchie informée"]}]}, {"position": 4, "label": "Rester vigilante face à d''éventuelles nouvelles sollicitations", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance future face à d''autres partenaires.", "groups": [{"position": 1, "keywords": ["vigilance future", "sollicitations nouvelles", "partenaires économiques"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('deonto-partialite-envers-une-partie', '{"slug": "deonto-partialite-envers-une-partie", "title": "Le ton change nettement selon la personne à qui il s''adresse", "theme_slug": "deontologie", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 18 heures. Lors d''une intervention conjointe, vous constatez que le ton de votre collègue change nettement selon la personne à laquelle il s''adresse parmi les protagonistes de cette situation, cette partialité restant perceptible dans le comportement et le registre employé plutôt que dans l''acte procédural lui-même qui reste formellement conforme aux règles applicables. Cette configuration, où cette différence de traitement se manifeste par une attitude plutôt que par une décision objectivement contestable, rend cette partialité difficile à qualifier formellement malgré son caractère pourtant manifeste à l''observation directe.\n\nCette situation, caractéristique des partialités qui s''expriment par le ton et le comportement plutôt que par des actes procéduraux formellement irréguliers, impose de rétablir l''équilibre du traitement sur place plutôt que de se contenter d''un simple constat a posteriori.\n\nCette configuration nécessite de rétablir l''équilibre du traitement sur place, cette action restant essentielle pour corriger immédiatement cette partialité comportementale constatée durant cette intervention conjointe.", "questions": [{"position": 1, "max_points": 5, "label": "Comment rétablissez-vous l''équilibre du traitement sur place face à cette partialité comportementale ?", "hint": "Ce rétablissement doit intervenir directement durant cette intervention, cette action restant nécessaire pour corriger immédiatement cette différence de traitement constatée chez ce collègue.", "perfect": "J''interviens directement pour rétablir un ton équilibré envers l''ensemble des protagonistes de cette situation, cette action restant nécessaire face à cette partialité constatée.\n\nJe reste attentive à traiter moi-même chacune des parties avec la même considération, cette égalité de traitement restant essentielle pour compenser ce déséquilibre.\n\nJe reste factuelle avec mon collègue sur cette différence de ton observée, cette clarté restant appropriée pour qu''il en prenne conscience durant cette intervention.\n\nJe reste attentive à ne pas aggraver cette situation par une confrontation ouverte avec ce collègue devant ces protagonistes présents.", "points": [{"position": 1, "label": "Intervenir directement pour rétablir un ton équilibré envers tous", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : action face à cette partialité constatée.", "groups": [{"position": 1, "keywords": ["ton équilibré", "partialité constatée", "action directe"]}]}, {"position": 2, "label": "Traiter soi-même chacune des parties avec la même considération", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Égalité de traitement compensant ce déséquilibre.", "groups": [{"position": 1, "keywords": ["égalité de traitement", "déséquilibre compensé", "considération égale"]}]}, {"position": 3, "label": "Rester factuelle avec ce collègue sur cette différence de ton observée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Prise de conscience durant cette intervention.", "groups": [{"position": 1, "keywords": ["différence observée", "prise de conscience", "clarté appliquée"]}]}, {"position": 4, "label": "Ne pas aggraver cette situation par une confrontation ouverte", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Confrontation évitée devant les protagonistes présents.", "groups": [{"position": 1, "keywords": ["confrontation évitée", "protagonistes présents", "situation non aggravée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment qualifiez-vous cette partialité comportementale malgré son caractère difficile à objectiver ?", "hint": "Cette qualification doit rester précise malgré la difficulté à objectiver formellement cette partialité, cette exigence restant essentielle pour reconnaître la réalité de ce manquement constaté.", "perfect": "Je qualifie clairement cette différence de ton comme une partialité comportementale, cette reconnaissance restant nécessaire malgré la difficulté à l''objectiver formellement.\n\nJe reste attentive à documenter mentalement les éléments concrets de cette différence de traitement observée durant cette intervention conjointe.\n\nJe reste factuelle sur le fait que l''acte procédural reste formellement conforme, cette distinction restant importante pour qualifier précisément cette situation.\n\nJe reste consciente que cette difficulté à objectiver cette partialité ne diminue pas sa réalité ni sa gravité pour les personnes concernées par ce traitement inégal.", "points": [{"position": 1, "label": "Qualifier clairement cette différence de ton comme une partialité comportementale", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : reconnaissance malgré la difficulté d''objectivation.", "groups": [{"position": 1, "keywords": ["partialité qualifiée", "comportement identifié", "objectivation difficile"]}]}, {"position": 2, "label": "Documenter mentalement les éléments concrets de cette différence", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Observation durant cette intervention conjointe.", "groups": [{"position": 1, "keywords": ["éléments documentés", "différence observée", "intervention conjointe"]}]}, {"position": 3, "label": "Rester factuelle sur la conformité formelle de l''acte procédural", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Distinction importante pour qualifier la situation.", "groups": [{"position": 1, "keywords": ["acte conforme", "distinction maintenue", "situation qualifiée"]}]}, {"position": 4, "label": "Reconnaître que cette difficulté d''objectivation ne diminue pas la gravité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réalité maintenue pour les personnes concernées.", "groups": [{"position": 1, "keywords": ["gravité maintenue", "réalité reconnue", "personnes concernées"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment abordez-vous ce sujet avec votre collègue une fois cette intervention terminée ?", "hint": "Cet abord doit rester constructif tout en restant clair sur ce constat, cette conciliation restant nécessaire pour une gestion appropriée de cette situation avec ce collègue.", "perfect": "J''aborde directement ce sujet avec mon collègue une fois cette intervention terminée, cette franchise restant nécessaire pour qu''il prenne conscience de cette partialité.\n\nJe reste factuelle sur les éléments concrets de cette différence de ton que j''ai observée durant cette intervention conjointe.\n\nJe reste attentive à comprendre les raisons éventuelles de cette différence de traitement, cette écoute restant utile sans pour autant excuser cette partialité constatée.\n\nJe reste attentive à envisager un signalement à ma hiérarchie si cette situation venait à se reproduire de manière récurrente avec ce collègue.", "points": [{"position": 1, "label": "Aborder directement ce sujet avec ce collègue après l''intervention", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : franchise nécessaire pour la prise de conscience.", "groups": [{"position": 1, "keywords": ["sujet abordé", "franchise nécessaire", "prise de conscience"]}]}, {"position": 2, "label": "Rester factuelle sur les éléments concrets de cette différence observée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éléments concrets de l''intervention conjointe.", "groups": [{"position": 1, "keywords": ["éléments concrets", "différence observée", "intervention décrite"]}]}, {"position": 3, "label": "Comprendre les raisons éventuelles sans excuser cette partialité", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Écoute sans validation du comportement constaté.", "groups": [{"position": 1, "keywords": ["raisons écoutées", "partialité non excusée", "compréhension recherchée"]}]}, {"position": 4, "label": "Envisager un signalement en cas de récurrence de cette situation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Signalement si le comportement se reproduit.", "groups": [{"position": 1, "keywords": ["signalement envisagé", "récurrence possible", "hiérarchie sollicitée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('deonto-secret-partage-avec-un-autre-service', '{"slug": "deonto-secret-partage-avec-un-autre-service", "title": "Un partenaire demande des éléments sur une famille suivie", "theme_slug": "deontologie", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 10 heures. Lors d''une réunion interinstitutionnelle, un partenaire social vous demande des éléments détaillés sur une famille déjà suivie par vos services, cette coopération entre institutions restant utile dans son principe mais cette demande dépassant potentiellement les limites appropriées du partage d''informations entre ces différents services. Cette configuration, où cette coopération utile entre en tension avec les bornes nécessaires qui encadrent ce partage interinstitutionnel, nécessite de partager le strict nécessaire à cette collaboration sans aller au-delà de ce qui reste réellement utile à ce partenaire.\n\nCette situation, caractéristique des échanges interinstitutionnels qui peuvent progressivement déraper vers un partage excessif d''informations sous couvert d''une coopération légitime, impose une vigilance sur les limites appropriées de cette transmission d''éléments sensibles.\n\nCette configuration nécessite de partager le strict nécessaire et pas au-delà, cette exigence restant essentielle pour concilier cette coopération utile avec le respect des bornes qui encadrent ce partage d''informations sensibles entre ces services.", "questions": [{"position": 1, "max_points": 5, "label": "Comment partagez-vous le strict nécessaire sans aller au-delà de cette limite appropriée ?", "hint": "Ce partage doit rester strictement limité à ce qui est réellement utile à cette coopération, cette mesure restant essentielle pour ne pas dépasser les bornes appropriées de cette transmission.", "perfect": "Je reste attentive à identifier précisément ce qui reste strictement nécessaire à cette coopération avec ce partenaire, cette limitation restant essentielle pour ce partage.\n\nJe reste factuelle sur les éléments que je peux effectivement transmettre dans ce cadre, cette rigueur restant appropriée pour ne pas dépasser cette limite nécessaire.\n\nJe reste attentive à ne pas céder à la facilité d''une transmission plus large sous prétexte de cette coopération interinstitutionnelle légitime.\n\nJe reste consciente que cette limitation reste appropriée même si ce partenaire pourrait souhaiter disposer d''informations plus complètes sur cette famille suivie.", "points": [{"position": 1, "label": "Identifier précisément ce qui reste strictement nécessaire à cette coopération", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : limitation essentielle pour ce partage.", "groups": [{"position": 1, "keywords": ["nécessaire identifié", "coopération limitée", "partage encadré"]}]}, {"position": 2, "label": "Rester factuelle sur les éléments effectivement transmissibles", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Rigueur ne dépassant pas cette limite.", "groups": [{"position": 1, "keywords": ["éléments précisés", "limite respectée", "rigueur maintenue"]}]}, {"position": 3, "label": "Ne pas céder à la facilité d''une transmission plus large", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance malgré cette coopération légitime.", "groups": [{"position": 1, "keywords": ["transmission limitée", "facilité évitée", "coopération légitime"]}]}, {"position": 4, "label": "Maintenir cette limitation malgré le souhait d''informations plus complètes", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Limitation maintenue face à cette demande.", "groups": [{"position": 1, "keywords": ["limitation maintenue", "informations complètes", "demande relativisée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment expliquez-vous à ce partenaire les limites de ce partage d''informations ?", "hint": "Cette explication doit rester claire et pédagogique, cette transparence restant appropriée pour que ce partenaire comprenne les raisons de cette limitation nécessaire.", "perfect": "J''explique clairement à ce partenaire les règles qui encadrent le partage de ces informations sensibles entre nos différentes institutions.\n\nJe reste factuelle sur les raisons de cette limitation, précisant que ces règles s''imposent indépendamment de la qualité de cette coopération que nous entretenons.\n\nJe reste attentive à ne pas donner l''impression d''un refus de coopérer, cette nuance restant importante pour préserver cette relation interinstitutionnelle.\n\nJe reste disponible pour envisager avec lui les modalités appropriées si des informations complémentaires s''avéraient réellement nécessaires à l''avenir.", "points": [{"position": 1, "label": "Expliquer clairement les règles encadrant ce partage d''informations", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : règles entre institutions expliquées.", "groups": [{"position": 1, "keywords": ["règles expliquées", "institutions concernées", "partage encadré"]}]}, {"position": 2, "label": "Préciser que ces règles s''imposent indépendamment de la coopération", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Limitation non liée à la qualité de la relation.", "groups": [{"position": 1, "keywords": ["règles constantes", "coopération distincte", "limitation justifiée"]}]}, {"position": 3, "label": "Ne pas donner l''impression d''un refus de coopérer", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Relation interinstitutionnelle préservée.", "groups": [{"position": 1, "keywords": ["coopération préservée", "impression évitée", "relation maintenue"]}]}, {"position": 4, "label": "Rester disponible pour envisager des modalités appropriées à l''avenir", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Informations complémentaires envisagées si nécessaire.", "groups": [{"position": 1, "keywords": ["modalités envisagées", "informations complémentaires", "avenir considéré"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment rendez-vous compte de cette sollicitation pour permettre un traitement approprié de cette demande ?", "hint": "Ce compte rendu doit permettre à votre hiérarchie d''apprécier la nature de cette demande et la réponse à y apporter, cette transmission restant utile pour ce type de sollicitation interinstitutionnelle.", "perfect": "Je transmets à ma hiérarchie cette sollicitation de ce partenaire, cette information restant utile pour une appréciation appropriée de cette demande interinstitutionnelle.\n\nJe reste factuelle sur la nature exacte des éléments demandés par ce partenaire, cette précision restant importante pour cette appréciation.\n\nJe reste attentive à signaler ma propre gestion de cette limitation, cette information permettant de valider mon appréciation initiale de cette situation.\n\nJe reste disponible pour toute précision complémentaire, cette réactivité restant utile pour ce type d''échange interinstitutionnel qui pourrait se reproduire.", "points": [{"position": 1, "label": "Transmettre cette sollicitation à la hiérarchie", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : appréciation appropriée de cette demande.", "groups": [{"position": 1, "keywords": ["sollicitation transmise", "demande interinstitutionnelle", "hiérarchie informée"]}]}, {"position": 2, "label": "Rester factuelle sur la nature exacte des éléments demandés", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Précision importante pour cette appréciation.", "groups": [{"position": 1, "keywords": ["éléments précisés", "demande décrite", "appréciation facilitée"]}]}, {"position": 3, "label": "Signaler sa propre gestion de cette limitation", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Validation de l''appréciation initiale.", "groups": [{"position": 1, "keywords": ["gestion signalée", "appréciation validée", "limitation appliquée"]}]}, {"position": 4, "label": "Rester disponible pour toute précision sur ce type d''échange", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réactivité pour de futurs échanges similaires.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "échange futur", "précision offerte"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('deonto-refus-de-porter-assistance-hors-service', '{"slug": "deonto-refus-de-porter-assistance-hors-service", "title": "Vous êtes en civil, une agression se déroule à vingt mètres", "theme_slug": "deontologie", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 20 heures. Alors que vous vous trouvez en civil et hors service, une agression se déroule à une vingtaine de mètres de vous dans cette rue, cette situation créant une tension entre le devoir d''assistance qui reste attaché à votre qualité de policier et l''absence de tout moyen ou tenue qui vous permettrait normalement d''intervenir dans des conditions habituelles de sécurité. Cette configuration, où cette absence d''équipement et de tenue complique considérablement votre intervention par rapport à un contexte de service normal, nécessite néanmoins d''alerter et d''agir dans la limite de vos moyens réels face à cette agression qui se déroule sous vos yeux.\n\nCette situation, caractéristique des situations hors service où le devoir d''assistance qui s''impose à tout policier rencontre les limites concrètes de moyens et d''équipement dont vous ne disposez pas dans ce contexte personnel, impose une action adaptée à ces circonstances particulières plutôt qu''une intervention identique à celle que vous mèneriez en service.\n\nCette configuration nécessite d''alerter et d''agir dans la limite de vos moyens réels, cette double exigence restant essentielle pour concilier ce devoir d''assistance avec la réalité de cette situation hors service et sans équipement.", "questions": [{"position": 1, "max_points": 5, "label": "Comment alertez-vous rapidement face à cette agression qui se déroule sous vos yeux ?", "hint": "Cette alerte doit intervenir rapidement, cette action restant nécessaire pour permettre l''intervention de moyens appropriés face à cette agression que vous constatez hors service.", "perfect": "J''alerte immédiatement les services compétents de cette agression en cours, cette action restant prioritaire compte tenu de l''urgence de cette situation constatée.\n\nJe reste factuelle et précise dans cette alerte, transmettant les éléments essentiels de localisation et de description de cette situation observée.\n\nJe reste attentive à préciser ma qualité de policier lors de cette alerte, cette information pouvant faciliter la coordination de l''intervention à venir.\n\nJe reste attentive à rester en observation de cette situation en attendant l''arrivée de ces moyens appropriés, cette vigilance restant utile pour orienter cette intervention.", "points": [{"position": 1, "label": "Alerter immédiatement les services compétents de cette agression", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : action prioritaire compte tenu de l''urgence.", "groups": [{"position": 1, "keywords": ["alerte immédiate", "services compétents", "urgence constatée"]}]}, {"position": 2, "label": "Rester factuelle et précise dans cette alerte transmise", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Localisation et description essentielles.", "groups": [{"position": 1, "keywords": ["alerte précise", "localisation transmise", "description fournie"]}]}, {"position": 3, "label": "Préciser sa qualité de policier lors de cette alerte", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Information facilitant la coordination.", "groups": [{"position": 1, "keywords": ["qualité précisée", "coordination facilitée", "policier identifié"]}]}, {"position": 4, "label": "Rester en observation en attendant l''arrivée des moyens appropriés", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance orientant l''intervention à venir.", "groups": [{"position": 1, "keywords": ["observation maintenue", "moyens attendus", "intervention orientée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment agissez-vous dans la limite de vos moyens réels face à cette agression ?", "hint": "Cette action doit rester adaptée à cette absence d''équipement et de tenue, cette limitation restant réelle et devant orienter votre comportement face à cette situation constatée hors service.", "perfect": "Je reste attentive à évaluer les moyens réels dont je dispose dans ce contexte hors service, cette évaluation restant nécessaire avant toute action directe.\n\nJe reste attentive à privilégier une action qui ne mette pas ma propre sécurité en danger de manière disproportionnée compte tenu de cette absence d''équipement.\n\nJe reste attentive à intervenir verbalement si cela peut contribuer à faire cesser cette agression sans nécessiter un contact physique direct et risqué.\n\nJe reste consciente que cette limitation de mes moyens ne diminue pas mon devoir d''assistance, mais doit adapter la forme concrète de mon intervention.", "points": [{"position": 1, "label": "Évaluer les moyens réels disponibles dans ce contexte hors service", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : évaluation nécessaire avant toute action.", "groups": [{"position": 1, "keywords": ["moyens évalués", "contexte hors service", "action préparée"]}]}, {"position": 2, "label": "Privilégier une action ne mettant pas sa sécurité en danger disproportionné", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Sécurité personnelle compte tenu de l''absence d''équipement.", "groups": [{"position": 1, "keywords": ["sécurité personnelle", "danger disproportionné", "équipement absent"]}]}, {"position": 3, "label": "Intervenir verbalement si cela peut faire cesser cette agression", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Alternative au contact physique direct.", "groups": [{"position": 1, "keywords": ["intervention verbale", "contact physique évité", "agression cessée"]}]}, {"position": 4, "label": "Adapter la forme de son intervention sans renoncer au devoir d''assistance", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Devoir maintenu malgré la limitation des moyens.", "groups": [{"position": 1, "keywords": ["devoir maintenu", "forme adaptée", "assistance assurée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous les suites de cette intervention une fois les secours professionnels arrivés ?", "hint": "Ces suites doivent permettre une transmission appropriée de votre témoignage et de votre qualité, cette gestion restant nécessaire pour faciliter la prise en charge de cette situation par ces professionnels arrivés.", "perfect": "Je me présente aux collègues arrivés en leur précisant ma qualité de policier et les circonstances de mon intervention initiale hors service.\n\nJe reste factuelle sur ce que j''ai pu observer de cette agression avant leur arrivée, cette information restant utile pour la suite de cette procédure.\n\nJe reste attentive à me tenir à disposition pour toute précision complémentaire que ces collègues pourraient nécessiter sur cette situation.\n\nJe reste attentive à rendre compte de cette intervention à ma propre hiérarchie une fois cette situation stabilisée, cette transmission restant appropriée compte tenu du contexte hors service.", "points": [{"position": 1, "label": "Se présenter aux collègues arrivés en précisant sa qualité et les circonstances", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : présentation facilitant la prise en charge.", "groups": [{"position": 1, "keywords": ["qualité présentée", "circonstances précisées", "collègues informés"]}]}, {"position": 2, "label": "Rester factuelle sur ce qui a été observé avant leur arrivée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information utile pour la suite de la procédure.", "groups": [{"position": 1, "keywords": ["observation rapportée", "procédure facilitée", "information utile"]}]}, {"position": 3, "label": "Se tenir à disposition pour toute précision complémentaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Disponibilité pour les collègues arrivés.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "précision offerte", "collègues assistés"]}]}, {"position": 4, "label": "Rendre compte de cette intervention à sa propre hiérarchie", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Transmission appropriée compte tenu du contexte hors service.", "groups": [{"position": 1, "keywords": ["hiérarchie informée", "contexte hors service", "intervention rapportée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('deonto-usage-tutoiement-et-familiarite', '{"slug": "deonto-usage-tutoiement-et-familiarite", "title": "Le tutoiement s''installe dès les premiers mots", "theme_slug": "deontologie", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 16 heures. Lors d''un contrôle sur la voie publique, votre collègue tutoie d''emblée la personne contrôlée dès les premiers mots de cet échange, cette habitude s''étant progressivement installée et banalisée au sein de votre équipe sans jamais avoir fait l''objet d''une remise en question explicite, ce registre de langage constituant pourtant un marqueur de considération qui affecte directement le respect dû à cette personne contrôlée. Cette configuration, où cette pratique s''est banalisée par la répétition sans jamais être questionnée, nécessite de maintenir un registre respectueux y compris envers les personnes déjà connues ou habituées à ce type de contrôle.\n\nCette situation, caractéristique des habitudes de langage qui s''installent progressivement dans une équipe sans jamais être remises en question malgré leur caractère potentiellement dégradant pour le respect dû aux usagers contrôlés, impose une vigilance particulière sur ce registre de langage employé.\n\nCette configuration nécessite de maintenir un registre respectueux y compris avec les habitués, cette exigence restant essentielle pour préserver la considération due à toute personne contrôlée indépendamment de la fréquence de ces contrôles antérieurs.", "questions": [{"position": 1, "max_points": 5, "label": "Comment maintenez-vous un registre respectueux malgré cette habitude installée au sein de votre équipe ?", "hint": "Ce registre respectueux doit être maintenu par vous-même, cette exemplarité restant utile pour contrebalancer cette habitude de tutoiement installée chez ce collègue.", "perfect": "Je maintiens personnellement un registre vouvoyant et respectueux envers cette personne contrôlée, cette constance restant essentielle indépendamment des habitudes de mon collègue.\n\nJe reste attentive à ce que ce registre respectueux reste la norme dans mes propres échanges avec l''ensemble des personnes que je contrôle sur ce secteur.\n\nJe reste consciente que cette habitude de tutoiement, même banalisée au sein de mon équipe, reste inappropriée et mérite d''être questionnée.\n\nJe reste attentive à ne pas me laisser entraîner par cette habitude collective qui pourrait progressivement affecter également ma propre pratique professionnelle.", "points": [{"position": 1, "label": "Maintenir personnellement un registre vouvoyant et respectueux", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : constance indépendante des habitudes du collègue.", "groups": [{"position": 1, "keywords": ["registre respectueux", "vouvoiement maintenu", "constance appliquée"]}]}, {"position": 2, "label": "Faire de ce registre respectueux la norme dans ses propres échanges", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Norme appliquée à l''ensemble des contrôles.", "groups": [{"position": 1, "keywords": ["norme établie", "échanges respectueux", "contrôles concernés"]}]}, {"position": 3, "label": "Reconnaître que cette habitude banalisée reste inappropriée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Habitude méritant d''être questionnée.", "groups": [{"position": 1, "keywords": ["habitude inappropriée", "banalisation reconnue", "question soulevée"]}]}, {"position": 4, "label": "Ne pas se laisser entraîner par cette habitude collective", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Pratique personnelle préservée face à l''habitude collective.", "groups": [{"position": 1, "keywords": ["entraînement évité", "pratique personnelle", "habitude collective"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment abordez-vous ce sujet avec votre collègue concerné par cette habitude de tutoiement ?", "hint": "Cet abord doit rester constructif, cette démarche restant utile pour que ce collègue prenne conscience de l''impact réel de cette pratique sur le respect dû aux personnes contrôlées.", "perfect": "J''aborde ce sujet avec mon collègue de manière posée, cette approche restant appropriée pour qu''il prenne conscience de cette habitude installée sans questionnement.\n\nJe reste factuelle sur l''impact que ce tutoiement peut avoir sur la perception de considération par la personne contrôlée, cette explication restant utile.\n\nJe reste attentive à ne pas culpabiliser excessivement ce collègue, cette mesure restant appropriée compte tenu du caractère banalisé et non intentionnellement irrespectueux de cette pratique.\n\nJe reste disponible pour échanger sur les bonnes pratiques de registre de langage à adopter systématiquement lors de ces contrôles.", "points": [{"position": 1, "label": "Aborder ce sujet de manière posée avec ce collègue", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : prise de conscience de cette habitude non questionnée.", "groups": [{"position": 1, "keywords": ["sujet abordé", "habitude questionnée", "prise de conscience"]}]}, {"position": 2, "label": "Expliquer l''impact de ce tutoiement sur la perception de considération", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Impact sur la personne contrôlée expliqué.", "groups": [{"position": 1, "keywords": ["impact expliqué", "considération perçue", "personne contrôlée"]}]}, {"position": 3, "label": "Ne pas culpabiliser excessivement ce collègue", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Mesure compte tenu du caractère non intentionnel.", "groups": [{"position": 1, "keywords": ["culpabilisation évitée", "caractère non intentionnel", "mesure appliquée"]}]}, {"position": 4, "label": "Rester disponible pour échanger sur les bonnes pratiques de langage", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Échange sur les pratiques à adopter systématiquement.", "groups": [{"position": 1, "keywords": ["bonnes pratiques", "échange proposé", "langage systématique"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous cette personne contrôlée qui vient d''être tutoyée par votre collègue ?", "hint": "Cette personne mérite une attention particulière compte tenu de ce tutoiement reçu, cette gestion devant permettre de compenser cette différence de registre au sein de ce même contrôle.", "perfect": "Je reste attentive à vouvoyer systématiquement cette personne dans mes propres échanges, cette constance restant utile pour compenser ce tutoiement reçu de mon collègue.\n\nJe reste factuelle et respectueuse dans l''ensemble de mes interventions durant ce contrôle, cette attitude restant appropriée indépendamment du registre employé par mon collègue.\n\nJe reste attentive à la réaction de cette personne face à cette différence de registre entre mon collègue et moi-même durant ce contrôle.\n\nJe reste consciente que cette compensation reste limitée et que la correction durable de cette pratique nécessite un travail plus large avec mon collègue.", "points": [{"position": 1, "label": "Vouvoyer systématiquement cette personne dans ses propres échanges", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : compensation du tutoiement reçu.", "groups": [{"position": 1, "keywords": ["vouvoiement systématique", "tutoiement compensé", "constance appliquée"]}]}, {"position": 2, "label": "Rester factuelle et respectueuse dans l''ensemble de ses interventions", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Attitude indépendante du registre du collègue.", "groups": [{"position": 1, "keywords": ["interventions respectueuses", "registre indépendant", "attitude constante"]}]}, {"position": 3, "label": "Rester attentive à la réaction de cette personne face à cette différence", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Différence de registre observée durant ce contrôle.", "groups": [{"position": 1, "keywords": ["réaction observée", "différence de registre", "contrôle en cours"]}]}, {"position": 4, "label": "Reconnaître que la correction durable nécessite un travail plus large", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Compensation limitée face à une correction durable.", "groups": [{"position": 1, "keywords": ["compensation limitée", "correction durable", "travail nécessaire"]}]}]}]}'::jsonb);